        {
            "id": 18,
            "number": "018",
            "title": "VARCHAR and CHAR",
            "cleanTitle": "VARCHAR and CHAR",
            "category": "MySQL Data Types",
            "introduction": "CHAR stores fixed-length character strings with space padding, whereas VARCHAR stores variable-length strings with a length prefix.",
            "learningObjective": "Compare storage mechanics, indexing efficiency, and use cases between fixed CHAR and dynamic VARCHAR.",
            "prerequisites": "Character encoding basics.",
            "requiredSchema": "`string_demo` table",
            "codeExample": "-- Compare fixed vs variable string allocations\nCREATE TABLE IF NOT EXISTS `string_demo` (\n    `country_code` CHAR(2) NOT NULL,       -- Fixed 2 characters (e.g. 'US', 'JP')\n    `hash_sha256` CHAR(64) NOT NULL,       -- Fixed 64 hex characters\n    `user_name` VARCHAR(50) NOT NULL       -- Dynamic 1 to 50 characters\n);\n\nINSERT INTO `string_demo` (`country_code`, `hash_sha256`, `user_name`)\nVALUES ('JP', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', 'NasaKun');\n\nSELECT `country_code`, `user_name`, LENGTH(`user_name`) AS byte_len FROM `string_demo`;",
            "expectedOutput": "+--------------+-----------+----------+\n| country_code | user_name | byte_len |\n+--------------+-----------+----------+\n| JP           | NasaKun   |        7 |\n+--------------+-----------+----------+\n1 row in set (0.00 sec)",
            "resultExplanation": "CHAR(2) allocates exactly 2 characters without length prefix overhead. VARCHAR(50) stores only the 7 actual characters of 'NasaKun' plus 1 length byte.",
            "notes": "Use CHAR for known fixed-length strings like ISO country codes (2 chars), currency codes (3 chars), or MD5/SHA256 hashes.",
            "commonMistakes": "Using CHAR(255) for short variable words, which wastes disk storage due to blank-padding on disk.",
            "requiresNewServer": false,
            "serverTag": "",
            "securityNotes": "Always limit VARCHAR size to the maximum reasonable length to prevent memory amplification during in-memory sorting.",
            "keywordsOrMethods": ["VARCHAR", "CHAR", "Variable-length", "Fixed-length", "LENGTH()"]
        },
